@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="badge bg-secondary">Total: @_allTasks.Count</span>
        <span class="badge bg-info">To Do: @GetColumnTasks("To Do").Count</span>
        <span class="badge bg-warning text-dark">In Progress: @GetColumnTasks("In Progress").Count</span>
        <span class="badge bg-success">Done: @GetColumnTasks("Done").Count</span>
        <span class="badge bg-danger">Overdue: @_allTasks.Count(t => t.DueDate < DateTime.Today && t.Status != "Done")</span>
    </div>

    <!-- Search Bar -->
    <div class="my-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="board-container">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            var colIndex = Array.IndexOf(_columns, column);

            <div class="board-column">
                <div class="column-header">
                    <h4>@column <span class="badge bg-secondary">@tasks.Count</span></h4>
                </div>

                <div class="column-body">
                    @foreach (var task in tasks)
                    {
                        <div class="task-card card mb-2">
                            <div class="card-body p-2">
                                <h6 class="card-title">@task.Title</h6>
                                <p class="card-text mb-1"><small>@task.Assignee</small></p>
                                <span class="badge priority-@task.Priority.ToLower()">@task.Priority</span>
                                <span class="text-muted ms-2"><small>@task.DueDate.ToString("MMM dd")</small></span>
                                <div class="mt-2">
                                    @if (colIndex > 0)
                                    {
                                        var leftStatus = _columns[colIndex - 1];
                                        <button class="btn btn-sm btn-outline-secondary me-1"
                                                @onclick="() => MoveTask(task.Id, leftStatus)">← Move Left</button>
                                    }
                                    @if (colIndex < _columns.Length - 1)
                                    {
                                        var rightStatus = _columns[colIndex + 1];
                                        <button class="btn btn-sm btn-outline-secondary"
                                                @onclick="() => MoveTask(task.Id, rightStatus)">Move Right →</button>
                                    }
                                </div>
                            </div>
                        </div>
                    }

                    @if (_showForm == column)
                    {
                        <div class="card mt-2">
                            <div class="card-body p-2">
                                <input type="text" class="form-control form-control-sm mb-1" placeholder="Title"
                                       @bind="_newTitle" />
                                <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee"
                                       @bind="_newAssignee" />
                                <select class="form-select form-select-sm mb-1" @bind="_newPriority">
                                    <option value="High">High</option>
                                    <option value="Medium">Medium</option>
                                    <option value="Low">Low</option>
                                </select>
                                <input type="date" class="form-control form-control-sm mb-1"
                                       @bind="_newDueDate" />
                                <button class="btn btn-sm btn-primary me-1" @onclick="() => SaveTask(column)">Save</button>
                                <button class="btn btn-sm btn-secondary" @onclick="CancelForm">Cancel</button>
                            </div>
                        </div>
                    }
                    else
                    {
                        <button class="btn btn-sm btn-outline-primary mt-2" @onclick="() => ShowAddForm(column)">+ Add Task</button>
                    }
                </div>
            </div>
        }
    </div>
}

<style>
    .stats-bar {
        display: flex;
        gap: 0.5rem;
        flex-wrap: wrap;
        margin-bottom: 1rem;
    }

    .board-container {
        display: flex;
        gap: 1rem;
    }

    .board-column {
        flex: 1;
        min-width: 250px;
        background: #f8f9fa;
        border-radius: 0.5rem;
        padding: 0.75rem;
    }

    .column-header h4 {
        font-size: 1.1rem;
        margin-bottom: 0.5rem;
    }

    .priority-high {
        background-color: #dc3545 !important;
        color: white;
    }

    .priority-medium {
        background-color: #ffc107 !important;
        color: black;
    }

    .priority-low {
        background-color: #198754 !important;
        color: white;
    }
</style>

@code {
    private readonly string[] _columns = { "To Do", "In Progress", "Done" };
    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;

    // Add form state
    private string? _showForm;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status) =>
        _allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrEmpty(_searchText) ||
                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.First(t => t.Id == taskId);
            _allTasks[_allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAddForm(string column)
    {
        _showForm = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelForm() => _showForm = null;

    private async Task SaveTask(string column)
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // The created task comes back with default status; update it if column isn't "To Do"
            if (column != "To Do")
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
                created = created with { Status = column };
            }
            _allTasks.Add(created);
            _showForm = null;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }
}

